    {
      "name": "Primary CTA Button (Blurple Filled)",
      "role": "Main call-to-action, e.g. 'Open Discord in your browser'",
      "description": "backgroundColor #5865F2, color #FFFFFF, borderRadius 12px, padding 19.5px 24px. No border visible — the blurple fill is self-contained. Hover shifts to #3442D9. The 19.5px vertical padding makes this the tallest button variant on the page — physically dominant in the CTA pair."
    },
    {
      "name": "Secondary CTA Button (White Filled)",
      "role": "Download prompt, paired with primary CTA",
      "description": "backgroundColor #FFFFFF, color #23272A, borderRadius 12px, padding 15px 24px. A clean white pill against the dark background — high contrast without blurple. Border is #23272A at 1px. The softer padding (vs primary) visually subordinates it as the secondary choice."
    },
    {
      "name": "Ghost Navigation Button (Transparent Outlined)",
      "role": "Nav dropdown triggers and secondary navigation actions",
      "description": "backgroundColor transparent, color #FFFFFF, border 1px solid #FFFFFF, borderRadius 12px, padding 10px 16px. Used for nav menu items with dropdown arrows. The all-white outline on dark keeps it visible without competing with blurple."
    },
    {
      "name": "Log In Button (White Outlined)",
      "role": "Top-right header authentication action",
      "description": "backgroundColor #FFFFFF, color #000000, border 1px solid #000000, borderRadius 16px, padding 10px 16px. Uses a larger 16px radius than other buttons — matches the pill-like header style. Appears on the light/frosted header strip, making the filled white surface legible against the nav background."
    },
    {
      "name": "Feature Showcase Card",
      "role": "Full-bleed section content containers holding product screenshots and feature copy",
      "description": "Large rounded containers with 24px+ radius, set against the page's deep blue background. Each card uses its own gradient or solid background (purple-to-magenta for 'Group Chats', green for 'Watch Together') — section identity is expressed through the card background color, not the page background. Content splits 50/50: product screenshot left, text right. Cards span full viewport width on mobile, max ~1100px on desktop."
    },
    {
      "name": "3D Character Float",
      "role": "Decorative mascot and character illustrations scattered at section edges",
      "description": "Not interactive UI — these are 3D-rendered PNG/WebP assets positioned absolutely at section boundaries, overlapping card edges. Sizes range from ~100px to ~300px. They exit and enter sections unpredictably, creating the 'world' atmosphere. No background, no border, no radius — raw edge compositing into the page."
    },
    {
      "name": "Product Screen Mock-up",
      "role": "Embedded Discord UI screenshots within feature cards",
      "description": "Screenshots of the actual Discord app rendered inside feature cards with 12-16px radius. They float slightly off-center with a subtle drop shadow. Mobile frames shown as phone outlines. Desktop frames shown as monitor bezels. The mock-ups use the real Discord dark UI (#2C2F33 surface, #23272A sidebar), grounding marketing claims in the actual product."
    },
    {
      "name": "Navigation Bar",
      "role": "Global top navigation",
      "description": "Fixed header spanning full viewport width. Background is semi-transparent over the hero image — appears near-white/frosted. Contains Discord wordmark left, text nav links center (16px ABC Ginto, #FFFFFF or #000000 depending on scroll state), and 'Log In' button far right. Dropdown triggers use the ghost outlined button variant. No visible shadow — floats as a flat strip."
    },
    {
      "name": "Hero Section",
      "role": "Full-viewport landing block",
      "description": "Full-bleed dark indigo background (#0E0F2D to near-black gradient implied). Headline in ABC Ginto Nord 800 at 56-61px, color #FFFFFF, all-caps, line-height 0.86, crammed into the left 50% of the viewport. Body copy at 16px ABC Ginto 400, color #FFFFFF, max-width ~380px. CTA pair (white + blurple buttons) sits below body. Right 50% holds the product mock-up composite with 3D characters overlapping both halves."
    },
    {
      "name": "Footer Navigation",
      "role": "Site-wide footer link groups",
      "description": "Dark background (#23272A or #000000). Multi-column link grid with group headings in 16px ABC Ginto 500 + positive letter-spacing. Link text at 16px/1.5 weight 400, color #BABCD9 (Fog) on dark. Discord wordmark and social icons top-left. No dividers — columns separated by gap only."
    }
